# DK HLS.  Hobro - Aalestrup
#
let hl = path("d3.dk.hls");

with detail = 3, railway = :first :pax :removed {
    # point.dk.Hobro  dk.FFH

    with link = "line.dk.HLS" {
        track(:ror, hl[:hob + 0.49sw, :hob.ya] << 0.5md << 1ms << 0.5mt);
        track(:ror, hl[:hob.ya - 0.1dl, :hob.xa] << 0.5md << 1ms << 0.5mt);
        track(
                hl[:hob.xa - 0.1dl, :hob.xa] << 0.5md << 1ms << 0.5mt
            ..  hl[:hob.za + 2md, :dos - 2.99km]
        );
        line_label(:left:ne, hl[:dos - 3km] << 0.5mt, "HLS");
        track(hl[:dos - 3.01km, :dos - 0.49sw]);
    }

    with link = "point.dk.Døstrup-Himmerland", railway = :station {
        track(hl[:dos - 0.5sw, :dos + 0.5sw]);
        marker(:right :de.hp, hl[:dos] >> 0.5mt);
        marker(:right :de.exbf, hl[:dos] >> 0.5mt);
        slabel(:right, hl[:dos] >> 0.5mt >> 1.4sh + (-5dt, -0.3dt),
            vbox(:left:bottom, " Døstrup", "Himmerland*")
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:dos + 0.49sw, :ror - 0.49sw]);
    }

    with link = "point.dk.Store-Rørbæk", railway = :station {
        track(hl[:ror - 0.5sw, :ror + 0.5sw]);
        marker(:left :de.hp, hl[:ror] << 0.5mt);
        slabel(:bottom, hl[:ror] << 0.5mt << 1sh + (2dt, 0.5dt),
            vbox(:center:top, "Store-", " Rørbæk*")
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:ror + 0.49sw, :gry - 0.49sw]);
    }

    with link = "point.dk.Grynderup", railway = :station {
        track(hl[:gry - 0.5sw, :gry + 0.5sw]);
        marker(:right :de.hp, hl[:gry] >> 0.5mt);
        slabel(:right, hl[:gry] >> 0.5mt >> 1sh + (-3dt, -1.2dt),
            "Grynderup"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:gry + 0.49sw, :nor - 0.49sw]);
    }

    with link = "point.dk.Nørager", railway = :station {
        track(hl[:nor - 0.5sw, :nor + 0.5sw]);
        marker(:right :de.bf, hl[:nor] >> 0.5mt);
        slabel(:top, hl[:nor] >> 0.5mt >> 1sh >> 0.4dt,
            "Nørager"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:nor + 0.49sw, :bol - 0.49sw]);
    }

    with link = "point.dk.Boldrup", railway = :station {
        track(hl[:bol - 0.5sw, :bol + 0.5sw]);
        marker(:left :de.hp, hl[:bol] << 0.5mt);
        slabel(:bottom, hl[:bol] << 0.5mt << 1sh + (2dt, 0.5dt),
            "Boldrup"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:bol + 0.49sw, :sim - 0.49sw]);
    }

    with link = "point.dk.Simested", railway = :station {
        track(hl[:sim - 0.5sw, :sim + 0.5sw]);
        marker(:right :de.hp, hl[:sim] >> 0.5mt);
        marker(:right :de.exbf, hl[:sim] >> 0.5mt);
        slabel(:right, hl[:sim] >> 0.5mt >> 1.4sh + (-3dt, -1.3dt),
            "Simested"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:sim + 0.49sw, :sim + 2.11km]);
        line_label(:right:s, hl[:sim + 2.1km] >> 0.5mt, "HLS");
        track(hl[:sim + 2.09km, :aal.xh - 2mt]);
        track(:lor,
                hl[:aal.xh - 2.1mt, :aal.xh - 2mt]
            ..  hl[:aal.yh, :aal.yh + 0.1dl] >> 1ms >> 1mt
        );
    }

    with link = "point.dk.Aalestrup", railway = :station {
        track(hl[:aal.yh, :aal + 350m]);
        track(
                hl[:aal.yh, :aal + 280m - 1dl] >> 1ms >> 1mt
            --  hl[:aal + 280m, :aal + 281m]
        );

        marker(:right :de.bf, hl[:aal] >> 1ms >> 1.5mt);
        slabel(:top :bold, hl[:aal] >> 1ms >> 1.5mt >> 1sh >> 0.3dt,
            "Aalestrup"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:aal + 349m, :obo - 0.49sw]);
    }

    with link = "point.dk.Østerbølle", railway = :station {
        track(hl[:obo - 0.5sw, :obo + 0.5sw]);
        marker(:left :de.hp, hl[:obo] << 0.5mt);
        slabel(:left, hl[:obo] << 0.5mt << 1sh + (-1.3dt, 1.1dt),
            "Østerbølle"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:obo + 0.49sw, :obo + 2.01km]);
        line_label(:left:se, hl[:obo + 2km] << 0.5mt, "HLS");
        track(hl[:obo + 1.99km, :oru - 0.49sw]);
    }

    with link = "point.dk.Østrup", railway = :station {
        track(hl[:oru - 0.5sw, :oru + 0.5sw]);
        marker(:left :de.bf, hl[:oru] << 0.5mt);
        slabel(:left, hl[:oru] << 0.5mt << 1sh + (-1.5dt, 0.3dt),
            "Østrup"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:oru + 0.49sw, :aar.yh - 1.79km]);
        line_label(:right:w, hl[:aar.yh - 1.8km] >> 0.5mt, "HLS");
        track(hl[:aar.yh - 1.81km, :aar.yh - 0.49seg]);
        track(:lor, hl[:aar.yh - 0.5seg, :aar.yh + 0.1dl]);
    }

    with link = "point.dk.Aars", railway = :station {
        track(hl[:aar.yh, :aar.ys] << 1ms << 1mt);
        track(hl[:aar.yh, :aar.ys]);
        marker(:right :de.bf, hl[:aar] >> 0.5mt);
        slabel(:right :bold, hl[:aar] >> 0.5mt >> 1sh + (1.2dt, 1.2dt),
            "Aars"
        );
    }

    with link = "line.dk.HLS" {
        track(:ror,
                hl[:aar.ys - 0.1dl, :aar.ys] << 1ms << 1mt
            ..  hl[:aar.xs + 2mt, :aar.xs + 2.1mt]
        );
        track(hl[:aar.xs + 2mt, :aar.xs + 1.51km]);
        line_label(:left:ne, hl[:aar.xs + 1.5km] << 0.5mt, "HLS");
        track(hl[:aar.xs + 1.49km, :hor - 0.49sw]);
    }

    with link = "point.dk.Hornum", railway = :station {
        track(hl[:hor - 0.5sw, :hor + 0.5sw]);
        marker(:right :de.bf, hl[:hor] >> 0.5mt);
        slabel(:right, hl[:hor] >> 0.5mt >> 1sh + (1.3dt, 0.4dt),
            "Hornum"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:hor + 0.49sw, :oje - 0.49sw]);
    }

    with link = "point.dk.Øjesø", railway = :station {
        track(hl[:oje - 0.5sw, :oje + 0.5sw]);
        marker(:left :de.hp, hl[:oje] << 0.5mt);
        slabel(:left, hl[:oje] << 0.5mt << 1sh + (-1.3dt, 0.5dt),
            "Øjesø"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:oje + 0.49sw, :gat - 0.49sw]);
    }

    with link = "point.dk.Gatten", railway = :station {
        track(hl[:gat - 0.5sw, :gat + 0.5sw]);
        marker(:left :de.hp, hl[:gat] << 0.5mt);
        marker(:left :de.exbf, hl[:gat] << 0.5mt);
        slabel(:right, hl[:gat] >> 0.5mt + (1.3dt, 0.3dt),
            "Gatten"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:gat + 0.49sw, :vin - 0.49sw]);
    }

    with link = "point.dk.Vindblæs", railway = :station {
        track(hl[:vin - 0.5sw, :vin + 0.5sw]);
        marker(:right :de.hp, hl[:vin] >> 0.5mt);
        marker(:right :de.exbf, hl[:vin] >> 0.5mt);
        slabel(:right, hl[:vin] >> 0.5mt >> 1.4sh + (1.3dt, 0.8dt),
            "Vindblæs"
        );
    }

    with link = "line.dk.HLS" {
        track(hl[:vin + 0.49sw, :log - 2.69km]);
        line_label(:right:sw, hl[:log - 2.7km] >> 0.5mt, "HLS");
        track(hl[:log - 2.71km, :log - 0.49sw]);
    }

    with link = "point.dk.Løgstør", railway = :station {
        track(hl[:log - 0.5sw, :log + 0.5sw]);
        marker(:left :de.bf, hl[:log] << 0.5mt);
        slabel(:bottom :bold, hl[:log] << 0.5mt << 1sh + (-2.5dt, 0.8dt),
            "Løgstør"
        );
    }
}

